-- Transaction-only fixtures. No provider calls, email sends or real charges.
begin;
create temp table ig_check_results(name text primary key) on commit drop;
create function pg_temp.ig_assert(ok boolean,label text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'Check failed: %',label;end if;insert into ig_check_results values(label);end$$;
do $$
declare owner_id uuid;session_id uuid;req uuid=gen_random_uuid();mail uuid=gen_random_uuid();p jsonb;r jsonb;claim jsonb;job jsonb;payload jsonb;snapshot jsonb;rejected boolean;secret text=repeat('a',64);issuer text;
begin
 select id into owner_id from auth.users where email='akm@indiagully.com';
 select id into session_id from auth.sessions where user_id=owner_id order by created_at desc limit 1;
 update ig_private.integration_root set secret_hash=encode(extensions.digest(convert_to(secret,'UTF8'),'sha256'),'hex');
 update ig_private.integration_config set mode='test',settings=settings||'{"max_payment_paise":1000000000}' where id='razorpay';
 update ig_private.integration_config set mode='enabled' where id='resend';
 perform pg_temp.ig_assert(not has_table_privilege('authenticated','public.ig_collection_links','insert') and not has_table_privilege('authenticated','public.ig_collection_links','update'),'Direct attribution changes forbidden');
 perform pg_temp.ig_assert(not has_table_privilege('authenticated','ig_private.collection_bindings','select'),'Provider credentials inaccessible to staff');
 perform pg_temp.ig_assert(not has_function_privilege('anon','public.ig_collection_manage(jsonb)','execute'),'Anonymous management forbidden');
 p=jsonb_build_object('action','prepare','request_id',req,'practice','horeca','confirmed',true,'invoice_ref','ROLLBACK-'||req,'description','Synthetic rollback collection; no provider request.','customer_name','Rollback Client','customer_email','collection-rollback@example.org','amount_paise',2500050,'expires_at',now()+interval '7 days','collector_name','Spoofed person','created_by',gen_random_uuid());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'session_id',session_id,'aal','aal1','role','authenticated')::text,true);
 rejected=false;begin perform public.ig_collection_manage(p);exception when insufficient_privilege then rejected=true;end;perform pg_temp.ig_assert(rejected,'MFA required');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'session_id',session_id,'aal','aal2','role','authenticated')::text,true);
 r=public.ig_collection_manage('{"action":"context"}');perform pg_temp.ig_assert(jsonb_array_length(r->'practices')=8,'Owner sees all permitted collection practices');
 r=public.ig_collection_manage(p);issuer=r->>'collector_name';perform pg_temp.ig_assert(r->>'created_by'=owner_id::text and issuer<>'Spoofed person','Issuer is server-derived and cannot be spoofed');
 perform pg_temp.ig_assert(r->>'reference' like 'IG-COL-%' and (r->>'amount_paise')::bigint=2500050,'Unique human reference and exact paise persist');
 r=public.ig_collection_manage(p);perform pg_temp.ig_assert((select count(*)=1 from public.ig_collection_links where id=req),'Repeat creation is idempotent');
 rejected=false;begin perform public.ig_collection_manage(p||'{"amount_paise":2500051}');exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Changed amount cannot reuse request identity');
 rejected=false;begin perform public.ig_collection_manage(p||jsonb_build_object('request_id',gen_random_uuid()));exception when unique_violation then rejected=true;end;perform pg_temp.ig_assert(rejected,'Duplicate invoice recipient and practice rejected');
 claim=public.ig_collection_manage(jsonb_build_object('action','claim','id',req,'operation','create'));
 rejected=false;begin perform public.ig_collection_manage(jsonb_build_object('action','claim','id',req,'operation','create'));exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Concurrent provider operation is leased once');
 rejected=false;begin perform public.ig_collection_server('wrong',jsonb_build_object('action','get','id',req));exception when insufficient_privilege then rejected=true;end;perform pg_temp.ig_assert(rejected,'Provider binding requires server secret');
 perform public.ig_collection_server(secret,claim||'{"action":"fail"}');
 r=public.ig_collection_manage(jsonb_build_object('action','claim','id',req,'operation','create'));perform pg_temp.ig_assert(r->>'reuse'='true','Uncertain outcome cannot blindly create another provider link');
 update public.ig_collection_links set checked_at=now()-interval '2 minutes' where id=req;
 claim=public.ig_collection_manage(jsonb_build_object('action','claim','id',req,'operation','refresh'));
 snapshot=claim||jsonb_build_object('action','finish','provider_id','plink_Rollback'||replace(req::text,'-',''),'short_url','https://rzp.io/i/RollbackFixture','provider_status','created','amount_paid',0);
 rejected=false;begin perform public.ig_collection_server(secret,snapshot||'{"amount_paid":9999999999}');exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Impossible provider totals rejected');
 r=public.ig_collection_server(secret,snapshot);perform pg_temp.ig_assert(r->>'status'='active','Verified provider creation activates link');
 update public.ig_profiles set display_name='Changed staff display' where id=owner_id;
 perform pg_temp.ig_assert((select collector_name=issuer from public.ig_collection_links where id=req),'Original staff identity remains after profile rename');
 p=jsonb_build_object('action','email','id',req,'request_id',mail,'recipient','collection-rollback@example.org','amount_paise',2500050,'confirmed',true);
 rejected=false;begin perform public.ig_collection_manage(p||'{"recipient":"different@example.org"}');exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Email review must match exact recipient');
 r=public.ig_collection_manage(p);perform pg_temp.ig_assert(r->>'status'='queued','Explicitly reviewed email queues once');
 r=public.ig_collection_manage(p);perform pg_temp.ig_assert((select count(*)=1 from public.ig_outbox where collection_link_id=req),'Email action idempotency prevents duplicate mail');
 rejected=false;begin perform public.ig_collection_manage(p||jsonb_build_object('request_id',gen_random_uuid()));exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Rapid duplicate email throttled');
 job=public.ig_delivery(secret,jsonb_build_object('action','claim','collection_link_id',req))->0;
 perform pg_temp.ig_assert(job->'collection'->>'collector_name'=issuer and job->'collection'->>'id'=req::text,'Delivery gets staff-attributed collection source');
 payload=jsonb_build_object('to',jsonb_build_array('collection-rollback@example.org'),'text','Rollback original branded message');
 r=public.ig_delivery(secret,jsonb_build_object('action','prepare','id',mail,'lease_token',job->>'lease_token','payload',payload));
 r=public.ig_delivery(secret,jsonb_build_object('action','prepare','id',mail,'lease_token',job->>'lease_token','payload',payload||'{"text":"changed"}'));
 perform pg_temp.ig_assert(r=payload,'Retried payment email keeps frozen reviewed bytes');
 perform public.ig_delivery(secret,jsonb_build_object('action','finish','id',mail,'lease_token',job->>'lease_token','provider_id','rollback-email-'||req));
 perform public.ig_delivery(secret,jsonb_build_object('action','event','event_id','rollback-delivered-'||req,'event','email.delivered','provider_id','rollback-email-'||req));
 perform pg_temp.ig_assert((select status='delivered' from public.ig_outbox where id=mail),'Signed-provider event pathway records delivered status');
 update public.ig_collection_links set created_at=now()-interval '10 minutes',checked_at=now()-interval '10 minutes' where id=req;
 job=public.ig_collection_server(secret,'{"action":"claim_due","mode":"test"}');
 select value into claim from jsonb_array_elements(job) where value->>'id'=req::text;
 perform pg_temp.ig_assert(claim is not null,'Scheduled worker claims due collections for verification');
 perform pg_temp.ig_assert(not exists(select 1 from jsonb_array_elements(public.ig_collection_server(secret,'{"action":"claim_due","mode":"test"}')) x where x->>'id'=req::text),'Scheduled workers cannot double-claim the same collection');
 perform public.ig_collection_server(secret,snapshot||claim);
 update public.ig_collection_links set checked_at=now()-interval '2 minutes' where id=req;
 claim=public.ig_collection_manage(jsonb_build_object('action','claim','id',req,'operation','refresh'));
 rejected=false;begin perform public.ig_collection_server(secret,snapshot||claim||'{"provider_status":"paid","amount_paid":1}');exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Partial amount cannot be marked paid');
 r=public.ig_collection_server(secret,snapshot||claim||'{"provider_status":"paid","amount_paid":2500050}');perform pg_temp.ig_assert(r->>'status'='paid' and r->>'collector_name'=issuer,'Full payment retains original collector');
 rejected=false;begin perform public.ig_collection_manage(p||jsonb_build_object('request_id',gen_random_uuid()));exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Paid link cannot trigger another payment request email');
 update public.ig_collection_links set checked_at=now()-interval '2 minutes' where id=req;
 claim=public.ig_collection_manage(jsonb_build_object('action','claim','id',req,'operation','refresh'));
 rejected=false;begin perform public.ig_collection_server(secret,snapshot||claim);exception when others then rejected=true;end;perform pg_temp.ig_assert(rejected,'Paid collection cannot regress on stale response');
 update public.ig_profiles set roles=array['client'] where id=owner_id;
 rejected=false;begin perform public.ig_collection_manage('{"action":"list"}');exception when insufficient_privilege then rejected=true;end;perform pg_temp.ig_assert(rejected,'Client role cannot access staff register');
 perform pg_temp.ig_assert(not ig_private.collection_allowed('horeca'),'Client role fails collection RLS policy');
end $$;
select count(*) as passed,array_agg(name order by name) as checks from ig_check_results;
rollback;
